<script setup lang="ts">withDefaults(defineProps<{ expanded?: boolean; selected?: boolean; disabled?: boolean }>(), { expanded: false, selected: false, disabled: false }); const emit = defineEmits<{ 'update:expanded': [value: boolean]; 'update:selected': [value: boolean] }>(); function onKeydown(event: KeyboardEvent) { if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); emit('update:selected', true) } if (event.key === 'ArrowRight') emit('update:expanded', true); if (event.key === 'ArrowLeft') emit('update:expanded', false) }</script>
<template><li class="ew-tree-item" role="treeitem" :aria-expanded="expanded" :aria-selected="selected" :aria-disabled="disabled" :tabindex="disabled ? -1 : 0" @keydown="onKeydown"><slot /></li></template>
